void dfs(int v) {
    marked[v] = true;
    preorder.add(v);                 // when first visited
    for (int w : adj.get(v)) {
        if (!marked[w]) {
            edgeTo[w] = v;
            dfs(w);
        }
    }
    postorder.add(v);                // when all neighbors are done
}

void bfs(int s) {
    Queue<Integer> q = new ArrayDeque<>();
    q.add(s); marked[s] = true; distTo[s] = 0;
    while (!q.isEmpty()) {
        int v = q.remove();
        for (int w : adj.get(v)) {
            if (!marked[w]) {
                marked[w] = true;            // mark when ENQUEUED
                edgeTo[w] = v;
                distTo[w] = distTo[v] + 1;
                q.add(w);
            }
        }
    }
}

