int shortestCycleThrough(List<List<Integer>> adj, int s) {
    int[] d = new int[adj.size()]; Arrays.fill(d, -1); d[s] = 0;
    Queue<Integer> q = new ArrayDeque<>(List.of(s));
    int best = Integer.MAX_VALUE;
    while (!q.isEmpty()) {
        int v = q.remove();
        for (int w : adj.get(v)) {
            if (w == s) best = Math.min(best, d[v] + 1);
            else if (d[w] == -1) { d[w] = d[v] + 1; q.add(w); }
        }
    }
    return best == Integer.MAX_VALUE ? -1 : best;
}

