List<Integer> traverse(List<List<Integer>> adj, int s) {
    boolean[] marked = new boolean[adj.size()];
    PriorityQueue<Integer> pq = new PriorityQueue<>();   // smallest label first
    pq.add(s);
    List<Integer> order = new ArrayList<>();
    while (!pq.isEmpty()) {
        int v = pq.poll();
        if (marked[v]) continue;
        marked[v] = true; order.add(v);
        for (int w : adj.get(v)) if (!marked[w]) pq.add(w);
    }
    return order;
}

