int fewestMoves(Map<String, List<String>> exits, String start, String goal) {
    Map<String, Integer> dist = new HashMap<>();
    Queue<String> q = new ArrayDeque<>();
    dist.put(start, 0); q.add(start);
    while (!q.isEmpty()) {
        String v = q.remove();
        if (v.equals(goal)) return dist.get(v);
        for (String w : exits.getOrDefault(v, List.of())) {
            if (!dist.containsKey(w)) { dist.put(w, dist.get(v) + 1); q.add(w); }
        }
    }
    return -1;
}
